import {visualAssets,drawCell} from './engine/visual-assets.js?v=22';
const TAU=Math.PI*2;
export function drawModernScenery(g,kind,seed=0){if(!visualAssets.scenery)return false;g.save();if(['citadelSun','citadelMoon','sanctuary','observatory'].includes(kind)&&visualAssets.landmarks){drawCell(g,visualAssets.landmarks,2,2,['citadelSun','citadelMoon','sanctuary','observatory'].indexOf(kind),-95,-185,190,190);}else if(kind==='tree'){const flower=seed%6===0;drawCell(g,visualAssets.scenery,3,2,flower?5:seed%4===0?1:0,flower?-35:-78,flower?-48:-165,flower?70:156,flower?60:180);}else if(kind==='rock'){drawCell(g,visualAssets.scenery,3,2,2,-42,-63,84,75);}else if(['ruin','pillar','lighthouse','portal'].includes(kind)){drawCell(g,visualAssets.scenery,3,2,3,-58,-113,116,124);}else if(kind==='house'){drawCell(g,visualAssets.scenery,3,2,4,-67,-112,134,124);}else{g.restore();return false;}g.restore();return true;}
export function drawModernMob(g,e,t){if(!visualAssets.mobs)return false;const kind=e.archetype||'wolf',cell=e.boss?5:({wolf:0,scorpion:1,construct:2,demon:3,spirit:4}[kind]??0),size=kind==='scorpion'?87:kind==='spirit'?67:85;g.save();const step=e.moving?Math.sin(t*9)*1.2:Math.sin(t*1.5)*.5;if(e.facing?.x+e.facing?.y<0)g.scale(-1,1);g.translate(e.winding>0?Math.sin(t*12)*.8:0,step+(kind==='spirit'?Math.sin(t*2)*3:0));g.rotate(e.winding>0?-.025:0);drawCell(g,visualAssets.mobs,3,2,cell,-size/2,-size+8,size,size);if(e.boss&&e.hp/e.maxHp<.3){g.globalCompositeOperation='lighter';g.globalAlpha=.12+.06*Math.sin(t*4);drawCell(g,visualAssets.mobs,3,2,cell,-size/2,-size+8,size,size);}g.restore();return true;}
export function drawAtmosphere(g,w,h,t,economy=false,region=0){g.save();g.globalCompositeOperation='screen';const light=g.createRadialGradient(w*.25,0,10,w*.25,0,w*.7);light.addColorStop(0,'#a9dcff12');light.addColorStop(.5,'#64aadf06');light.addColorStop(1,'#00000000');g.fillStyle=light;g.fillRect(0,0,w,h);for(let n=0;n<(economy?8:20);n++){const x=(n*137.1+t*(n%2?3:-2)+w*4)%w,y=(n*53.7-t*(2+n%3)+h*4)%h;g.globalAlpha=.15+.2*Math.sin(t*.8+n)**2;g.fillStyle=region===3?'#e0faff':region===1?'#ffb787':region===4?'#a9ffca':region===6?'#bba5ff':n%4?'#b5f4ff':'#ffe0a4';g.beginPath();g.arc(x,y,n%3? .6:1.1,0,TAU);g.fill();}g.restore();}
